import { expect, expectStatus, test } from "../../fixtures";

test("Approving every extraction approves the vendor", { tag: "@REV-05" }, async ({ apiAs, factory }) => {
  // Arrange
  const reviewer = await apiAs("reviewer");
  const { vendor, extractions } = await factory.vendorInReview();

  // Act
  for (const kind of ["w9", "insurance_certificate", "contract"] as const) {
    const response = await reviewer.post(`/api/extractions/${extractions[kind].id}/decision`, {
      data: { decision: "approve" },
    });
    const body = await expectStatus(response, 200);
    expect(body.status, `${kind} extraction is approved`).toBe("approved");
  }

  // Assert
  // Re-read the stored state rather than trusting the decision responses.
  const stored = await expectStatus(await reviewer.get(`/api/vendors/${vendor.id}`), 200);
  expect(stored.status).toBe("approved");

  const audit = await expectStatus(await reviewer.get(`/api/vendors/${vendor.id}/audit`), 200);
  const actions = audit.items.map((event: { action: string }) => event.action);
  expect(actions, await JSON.stringify(audit)).toContain("vendor.approved");
});
